import React from 'react';

export default function StudentSchedule() {
  const schedule = [
    {
      id: 1,
      courseName: "React Basics",
      day: "Monday",
      time: "10:00 AM - 11:30 AM",
      room: "Lab 101",
      instructor: "John Doe"
    },
    {
      id: 2,
      courseName: "JavaScript Advanced",
      day: "Tuesday",
      time: "2:00 PM - 3:30 PM",
      room: "Lab 202",
      instructor: "Jane Smith"
    },
    {
      id: 3,
      courseName: "React Basics",
      day: "Wednesday",
      time: "10:00 AM - 11:30 AM",
      room: "Lab 101",
      instructor: "John Doe"
    },
    {
      id: 4,
      courseName: "Web Design",
      day: "Thursday",
      time: "1:00 PM - 2:30 PM",
      room: "Lab 303",
      instructor: "Mike Johnson"
    },
    {
      id: 5,
      courseName: "JavaScript Advanced",
      day: "Friday",
      time: "2:00 PM - 3:30 PM",
      room: "Lab 202",
      instructor: "Jane Smith"
    }
  ];

  return (
    <div style={{ padding: '20px' }}>
      <h2>My Schedule</h2>
      
      {schedule.length === 0 ? (
        <p>No scheduled classes</p>
      ) : (
        <table style={{
          width: '100%',
          borderCollapse: 'collapse',
          marginTop: '20px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
        }}>
          <thead>
            <tr style={{
              background: '#007bff',
              color: 'white'
            }}>
              <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #0056b3' }}>Course Name</th>
              <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #0056b3' }}>Day</th>
              <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #0056b3' }}>Time</th>
              <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #0056b3' }}>Room</th>
              <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #0056b3' }}>Instructor</th>
            </tr>
          </thead>
          <tbody>
            {schedule.map((session, index) => (
              <tr key={session.id} style={{
                background: index % 2 === 0 ? '#f9f9f9' : '#ffffff',
                borderBottom: '1px solid #ddd'
              }}>
                <td style={{ padding: '12px' }}>{session.courseName}</td>
                <td style={{ padding: '12px' }}>{session.day}</td>
                <td style={{ padding: '12px' }}>{session.time}</td>
                <td style={{ padding: '12px' }}>{session.room}</td>
                <td style={{ padding: '12px' }}>{session.instructor}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
